add_action( 'wp_enqueue_scripts', static function () {
    wp_register_script_module( 'wpbp/helper', '/wp-content/wpbp/helper.js', array(), '1.0' );
    wp_register_script_module( 'wpbp/chart', '/wp-content/wpbp/chart.js', array(), '1.0' );
    wp_register_script_module(
        'wpbp/entry',
        '/wp-content/wpbp/entry.js',
        array(
            'wpbp/helper',
            array(
                'id'     => 'wpbp/chart',
                'import' => 'dynamic',
            ),
        ),
        '1.0'
    );
    wp_enqueue_script_module( 'wpbp/entry' );
} );

add_action( 'wp_enqueue_scripts', static function () {
    wp_enqueue_script( 'wpbp-base', '/wp-content/wpbp/base.js', array(), '1.0', array( 'strategy' => 'defer', 'in_footer' => true ) );
    wp_enqueue_script( 'wpbp-mid', '/wp-content/wpbp/mid.js', array( 'wpbp-base' ), '1.0', array( 'strategy' => 'defer', 'in_footer' => true ) );
    wp_enqueue_script( 'wpbp-leaf', '/wp-content/wpbp/leaf.js', array( 'wpbp-mid' ), '1.0', array( 'strategy' => 'defer', 'in_footer' => true ) );
    wp_add_inline_script( 'wpbp-leaf', 'var wpbpLeafConfig = ' . wp_json_encode( array( 'token' => 'wpbp-token-42' ) ) . ';', 'before' );
} );

function wpbp_performance_003(): void {
    register_block_type(
        'wpbp/notice',
        array(
            'api_version'     => 3,
            'render_callback' => static fn(): string => '<p class="wpbp-notice">Heads up</p>',
        )
    );
    wp_enqueue_block_style(
        'wpbp/notice',
        array(
            'handle' => 'wpbp-notice-style',
            'src'    => '/wp-content/wpbp/notice.css',
            'ver'    => '1.0',
        )
    );
}

add_filter(
    'script_module_data_wpbp/dashboard',
    static function ( array $data ): array {
        $data['home']  = home_url();
        $data['label'] = (string) get_option( 'wpbp_module_label', '' );
        return $data;
    }
);

add_filter(
    'wp_speculation_rules_href_exclude_paths',
    static function ( array $paths, string $mode ): array {
        $paths[] = '/wpbp-cart/*';
        $paths[] = '/wpbp-checkout/*';
        if ( 'prerender' === $mode ) {
            $paths[] = '/wpbp-preview/*';
        }
        return $paths;
    },
    10,
    2
);

add_filter(
    'wp_inline_script_attributes',
    static function ( array $attributes ): array {
        $nonce = (string) get_option( 'wpbp_csp_nonce', '' );
        if ( '' !== $nonce ) {
            $attributes['nonce'] = $nonce;
        }
        return $attributes;
    }
);

add_filter(
    'wp_lazy_loading_enabled',
    static function ( $default_value, $tag_name, $context ) {
        if ( 'img' === $tag_name && 'the_content' === $context ) {
            return false;
        }
        return $default_value;
    },
    10,
    3
);
